// PublishStoryboard marks a storyboard as published (read-only).
// Only the owning user may publish their own storyboard.
func (s *StoryboardService) PublishStoryboard(ctx context.Context, input PublishStoryboardInput) (*Storyboard, error) {
    if err := s.consumeBudget(ctx); err != nil {
        return nil, err
    }

    existing, err := s.repo.GetByID(ctx, input.ID)
    if err != nil {
        if errors.Is(err, ErrNotFound) {
            return nil, fmt.Errorf("PublishStoryboard: %w", ErrNotFound)
        }
        return nil, fmt.Errorf("PublishStoryboard get: %w", err)
    }
    if existing.OwnerID != input.OwnerID {
        return nil, fmt.Errorf("PublishStoryboard: %w", ErrForbidden)
    }
    if existing.Published {
        // Idempotent: already published, return as-is.
        return existing, nil
    }

    updated, err := s.repo.SetPublished(ctx, input.ID, true)
    if err != nil {
        return nil, fmt.Errorf("PublishStoryboard set: %w", err)
    }
    return updated, nil
}
```

